def gender(ru):
    w = ru.split()[-1]
    for suf in ('ость','ция','рия','ь','ня','ля','ка','га','жа','за','ша','ча','ща','на','ра','да','та','ла','ма','са','ва','на','ва','а','я'):
        if w.endswith(suf): return 'f'
    return 'm'

