    m = re.match(r'^(right|left|upper|lower|anterior|posterior|superior|inferior|medial|lateral|internal|external|great|major|minor|deep|superficial|accessory|transverse|ascending|descending|common|proper|long|short|broad|middle|distal|proximal|first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth) (.+)$', n)
    adj = None
    if m:
        adj = m.group(1); rest = m.group(2)
    else:
        rest = n
    # двусловные термины целиком (до разбора прилагательных)
