def main():
    atlas = json.load(open('/mnt/agents/output/app/public/atlas/models/atlas.json'))
    desc = {}
    for c in atlas['concepts']:
        d = make_desc(c['name'])
        if d:
            desc[c['name']] = d
    return desc

if __name__ == '__main__':
    print(json.dumps(main(), ensure_ascii=False, indent=0)[:500])
    print("total:", len(main()))
